from collections import deque

def minimum_weight(edges, queries):
    n = len(edges) + 1
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    LOG = max(1, n.bit_length())
    up = [[0] * n for _ in range(LOG)]  # up[k][v]: 2^k-th ancestor (root points to itself)
    depth = [0] * n
    dist = [0] * n

    seen = [False] * n
    seen[0] = True
    dq = deque([0])
    while dq:
        u = dq.popleft()
        for v, w in adj[u]:
            if not seen[v]:
                seen[v] = True
                up[0][v] = u
                depth[v] = depth[u] + 1
                dist[v] = dist[u] + w
                dq.append(v)

    for k in range(1, LOG):
        prev, cur = up[k - 1], up[k]
        for v in range(n):
            cur[v] = prev[prev[v]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for k in range(LOG):
            if (diff >> k) & 1:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG - 1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    def d(u, v):
        return dist[u] + dist[v] - 2 * dist[lca(u, v)]

    ans = []
    for a, b, c in queries:
        ans.append((d(a, b) + d(a, c) + d(b, c)) // 2)
    return ans
